package dev.hrutvik.billing.credit;
import com.fasterxml.jackson.databind.ObjectMapper; import dev.hrutvik.billing.outbox.*; import org.junit.jupiter.api.Test; import java.math.BigDecimal; import java.time.*; import java.util.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
class CreditServiceTest {
 private final CreditStore store=mock(CreditStore.class);private final OutboxEventRepository outbox=mock(OutboxEventRepository.class);private final Instant now=Instant.parse("2026-11-06T12:00:00Z");private final CreditService service=new CreditService(store,outbox,new ObjectMapper(),Clock.fixed(now,ZoneOffset.UTC));private final UUID invoice=UUID.randomUUID();
 @Test void issuesPartialCreditAndEventAtomically(){when(store.find("tenant-a","key-1")).thenReturn(Optional.empty());when(store.lockInvoice("tenant-a",invoice)).thenReturn(new InvoiceBalance(invoice,"USD",new BigDecimal("100.00"),new BigDecimal("25.00")));var result=service.issue("tenant-a",invoice,"key-1",new CreditRequest(new BigDecimal("10"),"Service outage"));assertThat(result.amount()).isEqualByComparingTo("10.00");assertThat(result.replayed()).isFalse();verify(store).insert(any(),startsWith("CR-"),eq("tenant-a"),eq(invoice),eq("USD"),eq(new BigDecimal("10.00")),eq("Service outage"),eq("key-1"),argThat(s->s.length()==64),eq(now));verify(outbox).save(argThat(e->"billing.credit-note-issued.v1".equals(e.getDestination())));}
 @Test void preventsConcurrentOverCreditUsingRemainingBalance(){when(store.find(any(),any())).thenReturn(Optional.empty());when(store.lockInvoice("tenant-a",invoice)).thenReturn(new InvoiceBalance(invoice,"USD",new BigDecimal("100.00"),new BigDecimal("95.00")));assertThatThrownBy(()->service.issue("tenant-a",invoice,"key-2",new CreditRequest(new BigDecimal("10"),"Adjustment"))).isInstanceOf(IllegalArgumentException.class).hasMessageContaining("remaining invoice balance");verify(store,never()).insert(any(),any(),any(),any(),any(),any(),any(),any(),any(),any());}
 @Test void exactReplayReturnsOriginalWithoutSecondEvent(){var stored=new CreditStore.StoredCredit(UUID.randomUUID(),"CR-EXIST",invoice,"USD",new BigDecimal("10.00"),"Service outage",now,fingerprint(invoice,new BigDecimal("10"),"Service outage"));when(store.find("tenant-a","key-1")).thenReturn(Optional.of(stored));assertThat(service.issue("tenant-a",invoice,"key-1",new CreditRequest(new BigDecimal("10.00"),"Service outage")).replayed()).isTrue();verifyNoInteractions(outbox);verify(store,never()).lockInvoice(any(),any());}
 @Test void conflictingKeyReuseIsRejected(){var stored=new CreditStore.StoredCredit(UUID.randomUUID(),"CR-EXIST",invoice,"USD",new BigDecimal("10.00"),"Service outage",now,fingerprint(invoice,new BigDecimal("10"),"Service outage"));when(store.find("tenant-a","key-1")).thenReturn(Optional.of(stored));assertThatThrownBy(()->service.issue("tenant-a",invoice,"key-1",new CreditRequest(new BigDecimal("11"),"Service outage"))).isInstanceOf(CreditConflictException.class);}
 private String fingerprint(UUID id,BigDecimal amount,String reason){try{String v=id+"|"+amount.stripTrailingZeros().toPlainString()+"|"+reason;return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(v.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception e){throw new RuntimeException(e);}}
}
